import numpy as np


def heilbronn_convex13() -> np.ndarray:
    """Deterministic multi-topology soft-min search with exact epigraph polish."""
    n = 13
    triples = np.array(
        [(i, j, k) for i in range(n) for j in range(i + 1, n)
         for k in range(j + 1, n)], dtype=int
    )

    center = np.array([0.5, 0.5])
    interior = np.array([
        [0.37, 0.37], [0.63, 0.37], [0.50, 0.50],
        [0.37, 0.63], [0.63, 0.63], [0.50, 0.31],
        [0.50, 0.69], [0.31, 0.50], [0.69, 0.50],
        [0.43, 0.50], [0.57, 0.50]
    ])

    seeds = []
    # Includes the original useful contact counts and two additional
    # hull/interior balance classes.
    for m in (6, 7, 8, 9, 10, 11):
        angles = np.linspace(0.0, 2.0 * np.pi, m, endpoint=False)
        for reflected in (False, True):
            phase = 0.17 if reflected else -0.11
            radii = 0.435 + 0.018 * np.cos(3.0 * angles + phase)
            rr = radii[::-1] if reflected else radii
            hull = center + rr[:, None] * np.column_stack(
                (np.cos(angles), np.sin(angles))
            )
            if reflected:
                hull[:, 1] = 1.0 - hull[:, 1]
            count = n - m
            inner = interior[:count].copy()
            idx = np.arange(count)
            inner[:, 0] += 0.012 * np.sin(idx + m)
            inner[:, 1] += 0.010 * np.cos(1.7 * idx + m)
            seeds.append(np.vstack((hull, inner)))

    base = seeds[1].copy()

    try:
        from scipy.optimize import minimize
        from scipy.spatial import ConvexHull
        from scipy.special import logsumexp
    except Exception:
        return base

    def dets(p):
        a = p[triples[:, 0]]
        b = p[triples[:, 1]]
        c = p[triples[:, 2]]
        return ((b[:, 0] - a[:, 0]) * (c[:, 1] - a[:, 1])
                - (b[:, 1] - a[:, 1]) * (c[:, 0] - a[:, 0]))

    def score(p):
        try:
            area = ConvexHull(p).volume
        except Exception:
            return 0.0
        if not np.isfinite(area) or area <= 1e-12:
            return 0.0
        return float(0.5 * np.min(np.abs(dets(p))) / area)

    def soft_objective(x, temperature):
        p = x.reshape(n, 2)
        try:
            area = ConvexHull(p).volume
        except Exception:
            return 1e5
        if not np.isfinite(area) or area <= 1e-12:
            return 1e5
        values = 0.5 * np.abs(dets(p)) / area
        return float(temperature * logsumexp(-values / temperature))

    best = base.copy()
    best_value = score(best)

    ranked = sorted(
        ((soft_objective(s.ravel(), 0.001), s) for s in seeds),
        key=lambda x: x[0]
    )

    # The additional contact classes are explored without substantially
    # increasing the number of expensive full continuations.
    for _, start in ranked[:5]:
        x = start.ravel().copy()
        for temp in (0.004, 0.0015, 0.0005, 0.00012):
            result = minimize(
                lambda z, t=temp: soft_objective(z, t),
                x,
                method="L-BFGS-B",
                bounds=[(0.002, 0.998)] * (2 * n),
                options={"maxiter": 450, "ftol": 1e-13,
                         "gtol": 1e-8, "maxls": 40}
            )
            if np.isfinite(result.fun):
                x = result.x
        candidate = x.reshape(n, 2)
        value = score(candidate)
        if value > best_value:
            best, best_value = candidate.copy(), value

    # Exact normalized maximin polish with fixed local hull combinatorics.
    try:
        hull = ConvexHull(best)
        order = hull.vertices
        signed = np.sign(dets(best))
        signed[signed == 0.0] = 1.0

        def polygon_area(p):
            q = p[order]
            return 0.5 * (
                np.dot(q[:, 0], np.roll(q[:, 1], -1))
                - np.dot(q[:, 1], np.roll(q[:, 0], -1))
            )

        def constraints(z):
            p = z[:-1].reshape(n, 2)
            t = z[-1]
            q = p[order]
            area = polygon_area(p)
            tri = 0.5 * signed * dets(p) - t * area
            edges = np.roll(q, -1, axis=0) - q
            contain = (
                edges[:, None, 0] * (p[None, :, 1] - q[:, None, 1])
                - edges[:, None, 1] * (p[None, :, 0] - q[:, None, 0])
            )
            turns = np.roll(q, -1, axis=0) - q
            nxt = np.roll(turns, -1, axis=0)
            convex = turns[:, 0] * nxt[:, 1] - turns[:, 1] * nxt[:, 0]
            return np.concatenate(
                (tri, contain.ravel(), convex, np.array([area - 1e-5]))
            )

        z0 = np.concatenate((best.ravel(), [best_value * 0.999]))
        result = minimize(
            lambda z: -z[-1],
            z0,
            method="SLSQP",
            bounds=[(0.0001, 0.9999)] * (2 * n) + [(0.0, 0.1)],
            constraints={"type": "ineq", "fun": constraints},
            options={"maxiter": 500, "ftol": 1e-12, "disp": False}
        )
        if np.isfinite(result.fun):
            candidate = result.x[:-1].reshape(n, 2)
            value = score(candidate)
            if value > best_value:
                best, best_value = candidate.copy(), value
    except Exception:
        pass

    return np.asarray(np.clip(best, 0.0, 1.0), dtype=float)

